import React, { useEffect, useState } from "react";
import axios from "axios";
import { useLocation, useNavigate } from "react-router-dom";
import ProductCard from "./ProductCard";
import "./global.css";

export default function Home() {
  const [products, setProducts] = useState([]);
  const location = useLocation();
  const navigate = useNavigate();

  const swapFor = location.state?.swapFor || null;

  useEffect(() => {
    axios
      .get("http://localhost:5001/api/products")
      .then((res) => setProducts(res.data))
      .catch((err) => console.log(err));
  }, []);

  const handleSwapSelection = async (selectedProduct) => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) {
      alert("Please login to send swap request");
      navigate("/login");
      return;
    }

    // PRICE CHECK
    const diff = Math.abs(
      Number(selectedProduct.price) - Number(swapFor.price)
    );

    if (diff > 200) {
      alert(`Swap failed ❌ Price difference ₹${diff} exceeds 200`);
      return;
    }

    // SEND REQUEST
    const res = await axios.post("http://localhost:5001/api/swaps/create", {
      offeredProductId: selectedProduct._id,
      productWantedId: swapFor._id,
      requestedById: user._id,
    });

    if (res.data.success) {
      alert("Swap request sent! 🎉");
    }
  };

  return (
    <div className="home-page">
      <div className="hero-section">
        <h1>Welcome to Rewear</h1>
        <p className="tagline">Buy • Sell • Swap • Sustain 🌱</p>
      </div>

      {swapFor ? (
        <h2 className="section-title">
          Select a product to swap with your "{swapFor.title}"
        </h2>
      ) : (
        <h2 className="section-title">Featured Products</h2>
      )}

      <div className="product-grid">
        {products.map((p) => (
          <ProductCard
            key={p._id}
            product={p}
            swapMode={!!swapFor}
            onSwapSelect={() => handleSwapSelection(p)}
          />
        ))}
      </div>
    </div>
  );
}
